1	package com.example.starter.service.impl;
2	
3	import java.math.BigDecimal;
4	import java.time.Clock;
5	import java.time.Duration;
6	import java.time.Instant;
7	import java.time.LocalDate;
8	import java.time.ZoneOffset;
9	import java.util.ArrayList;
10	import java.util.HashSet;
11	import java.util.List;
12	import java.util.Set;
13	
14	import org.springframework.dao.DuplicateKeyException;
15	import org.springframework.stereotype.Service;
16	
17	import com.example.starter.api.dto.ActionResult;
18	import com.example.starter.api.dto.CardView;
19	import com.example.starter.api.dto.CoverageRequest;
20	import com.example.starter.api.dto.DispatchRequest;
21	import com.example.starter.api.dto.InspectionRequest;
22	import com.example.starter.api.dto.ReleaseRequest;
23	import com.example.starter.api.dto.ToolRegisterRequest;
24	import com.example.starter.api.dto.TorqueRequest;
25	import com.example.starter.api.dto.TorqueResult;
26	import com.example.starter.api.dto.TraceView;
27	import com.example.starter.api.dto.WitnessRequest;
28	import com.example.starter.api.dto.WitnessResult;
29	import com.example.starter.domain.CardStatus;
30	import com.example.starter.domain.TorqueMath;
31	import com.example.starter.domain.WitnessStatus;
32	import com.example.starter.persistence.CardRepository;
33	import com.example.starter.persistence.CardRow;
34	import com.example.starter.persistence.FastenerRow;
35	import com.example.starter.persistence.InspectionRepository;
36	import com.example.starter.persistence.ReleaseRepository;
37	import com.example.starter.persistence.ToolRepository;
38	import com.example.starter.persistence.TorqueRepository;
39	import com.example.starter.persistence.WitnessRepository;
40	import com.example.starter.service.IdempotencyExecutor;
41	import com.example.starter.service.OperationService;
42	import com.example.starter.service.Outcome;
43	import com.example.starter.support.ApiException;
44	
45	/**
46	 * 航空装配力矩紧固与见证点控制核心服务。
47	 *
48	 * <p>所有携带 requestId 的变更操作经 {@link IdempotencyExecutor} 包裹：业务动作与台账同事务提交，
49	 * 失败结果另起事务登记。返工与力矩记录在同一事务内追加，原始力矩记录永不覆盖。
50	 */
51	@Service
52	public class OperationServiceImpl implements OperationService {
53	
54	    /** 见证等待升级时长：2 小时，恰满（含边界）即升级。 */
55	    static final Duration WITNESS_WAIT_LIMIT = Duration.ofHours(2);
56	    /** 同一紧固点最大返工次数：恰 2 次合法，第 3 次测量仍超差则整批隔离。 */
57	    static final int MAX_REWORKS = 2;
58	    private static final BigDecimal DEFAULT_TOLERANCE_PCT = new BigDecimal("5.00");
59	
60	    private final Clock clock;
61	    private final IdempotencyExecutor idempotencyExecutor;
62	    private final CardRepository cardRepository;
63	    private final TorqueRepository torqueRepository;
64	    private final InspectionRepository inspectionRepository;
65	    private final WitnessRepository witnessRepository;
66	    private final ReleaseRepository releaseRepository;
67	    private final ToolRepository toolRepository;
68	
69	    public OperationServiceImpl(Clock clock,
70	                                IdempotencyExecutor idempotencyExecutor,
71	                                CardRepository cardRepository,
72	                                TorqueRepository torqueRepository,
73	                                InspectionRepository inspectionRepository,
74	                                WitnessRepository witnessRepository,
75	                                ReleaseRepository releaseRepository,
76	                                ToolRepository toolRepository) {
77	        this.clock = clock;
78	        this.idempotencyExecutor = idempotencyExecutor;
79	        this.cardRepository = cardRepository;
80	        this.torqueRepository = torqueRepository;
81	        this.inspectionRepository = inspectionRepository;
82	        this.witnessRepository = witnessRepository;
83	        this.releaseRepository = releaseRepository;
84	        this.toolRepository = toolRepository;
85	    }
86	
87	    // ------------------------------------------------------------------
88	    // 派工
89	    // ------------------------------------------------------------------
90	
91	    @Override
92	    public Outcome dispatch(DispatchRequest request) {
93	        validateDispatch(request);
94	        return idempotencyExecutor.execute(request.requestId(), "DISPATCH", request, () -> {
95	            Instant now = clock.instant();
96	            try {
97	                cardRepository.insertGuard(request.station(), request.cardNo(), now);
98	            } catch (DuplicateKeyException stationBusy) {
99	                throw ApiException.conflict("STATION_BUSY",
100	                        "工位 " + request.station() + " 已存在执行中工序卡");
101	            }
102	            long cardId;
103	            try {
104	                cardId = cardRepository.insertCard(request.cardNo(), request.station(), request.productSn(),
105	                        request.witnessPoint(), request.operator(), now);
106	            } catch (DuplicateKeyException cardNoExists) {
107	                throw ApiException.conflict("CARD_NO_EXISTS", "工序卡号已存在: " + request.cardNo());
108	            }
109	            for (DispatchRequest.FastenerSpec spec : request.fasteners()) {
110	                BigDecimal tolerance = spec.tolerancePct() == null
111	                        ? DEFAULT_TOLERANCE_PCT : spec.tolerancePct();
112	                cardRepository.insertFastener(cardId, spec.pointCode(), spec.nominalTorque(), tolerance);
113	            }
114	            CardRow card = requireCard(request.cardNo());
115	            return Outcome.of(201, toView(card));
116	        });
117	    }
118	
119	    private void validateDispatch(DispatchRequest request) {
120	        if (request.fasteners() == null || request.fasteners().isEmpty()) {
121	            throw ApiException.badRequest("FASTENERS_REQUIRED", "派工至少包含一个紧固点");
122	        }
123	        Set<String> points = new HashSet<>();
124	        for (DispatchRequest.FastenerSpec spec : request.fasteners()) {
125	            if (!points.add(spec.pointCode())) {
126	                throw ApiException.badRequest("DUPLICATE_POINT", "紧固点编号重复: " + spec.pointCode());
127	            }
128	            if (spec.tolerancePct() != null
129	                    && spec.tolerancePct().compareTo(BigDecimal.ZERO) <= 0) {
130	                throw ApiException.badRequest("TOLERANCE_INVALID", "允差必须为正数");
131	            }
132	        }
133	    }
134	
135	    // ------------------------------------------------------------------
136	    // 力矩紧固测量
137	    // ------------------------------------------------------------------
138	
139	    @Override
140	    public Outcome measure(TorqueRequest request) {
141	        return idempotencyExecutor.execute(request.requestId(), "TORQUE_MEASURE", request, () -> {
142	            CardRow card = requireCard(request.cardNo());
143	            Instant now = clock.instant();
144	
145	            // 终态：归档后迟到测量只记迟到事件，不改变工序状态。
146	            if (card.status() == CardStatus.ARCHIVED) {
147	                torqueRepository.insertLateEvent(card.id(), request.pointCode(), request.measuredTorque(),
148	                        request.operator(), request.toolCode(), now, request.requestId());
149	                TorqueResult late = new TorqueResult(card.cardNo(), request.pointCode(), 0, null,
150	                        request.measuredTorque(), null, false, null, card.status().name(), true, now);
151	                return Outcome.of(200, late);
152	            }
153	            // 隔离评审冻结：不再受理新测量。
154	            if (card.status() == CardStatus.QUARANTINED) {
155	                throw ApiException.unprocessable("CARD_QUARANTINED",
156	                        "工序卡已整批隔离评审，冻结受理力矩测量");
157	            }
158	            if (card.status() != CardStatus.DISPATCHED) {
159	                throw ApiException.unprocessable("CARD_NOT_IN_TIGHTENING",
160	                        "当前状态 " + card.status() + " 不受理力矩测量");
161	            }
162	            FastenerRow fastener = cardRepository.findFastener(card.id(), request.pointCode());
163	            if (fastener == null) {
164	                throw ApiException.notFound("FASTENER_NOT_FOUND",
165	                        "紧固点不存在: " + request.pointCode());
166	            }
167	            assertToolValidToday(request.toolCode());
168	
169	            int attempts = torqueRepository.countAttempts(card.id(), fastener.id());
170	            int reworks = torqueRepository.countReworks(card.id(), fastener.id());
171	            int attemptNo = attempts + 1;
172	            BigDecimal deviation = TorqueMath.deviationPct(fastener.nominalTorque(), request.measuredTorque());
173	            boolean pass = TorqueMath.inTolerance(fastener.nominalTorque(), request.measuredTorque(),
174	                    fastener.tolerancePct());
175	
176	            // 力矩记录追加（永不覆盖）。
177	            torqueRepository.insertTorque(new TorqueRepository.TorqueRow(
178	                    0, card.id(), fastener.id(), attemptNo, request.measuredTorque(), deviation, pass,
179	                    request.operator(), request.toolCode(), now, request.requestId()));
180	
181	            Integer reworkNo = null;
182	            if (!pass) {
183	                if (reworks < MAX_REWORKS) {
184	                    // 超差即返工并记录；返工台账与力矩链同一事务追加。
185	                    reworkNo = reworks + 1;
186	                    String reason = "实测 " + request.measuredTorque() + " N·m，偏差 " + deviation
187	                            + "%，超出 ±" + fastener.tolerancePct() + "%";
188	                    torqueRepository.insertRework(new TorqueRepository.ReworkRow(
189	                            0, card.id(), fastener.id(), reworkNo, request.requestId(), reason, now), now);
190	                } else {
191	                    // 已返工恰 2 次后第 3 次测量仍超差：整批隔离评审。
192	                    cardRepository.markQuarantined(card.id(), now);
193	                    card = requireCard(card.cardNo());
194	                    TorqueResult quarantined = new TorqueResult(card.cardNo(), request.pointCode(), attemptNo,
195	                            fastener.nominalTorque(), request.measuredTorque(), deviation, false, null,
196	                            CardStatus.QUARANTINED.name(), false, now);
197	                    return Outcome.of(422, quarantined);
198	                }
199	            }
200	
201	            // 全部紧固点最近一次测量均合格 → 力矩紧固阶段完成。
202	            int fastenerCount = cardRepository.listFasteners(card.id()).size();
203	            if (torqueRepository.allFastenersLastAttemptPassing(card.id(), fastenerCount)) {
204	                cardRepository.updateStatusIfCurrent(card.id(), CardStatus.DISPATCHED, CardStatus.TIGHTENED);
205	            }
206	            card = requireCard(card.cardNo());
207	            return Outcome.of(200, new TorqueResult(card.cardNo(), request.pointCode(), attemptNo,
208	                    fastener.nominalTorque(), request.measuredTorque(), deviation, pass, reworkNo,
209	                    card.status().name(), false, now));
210	        });
211	    }
212	
213	    private void assertToolValidToday(String toolCode) {
214	        ToolRepository.ToolRow tool = toolRepository.findByCode(toolCode);
215	        if (tool == null) {
216	            throw ApiException.unprocessable("TOOL_NOT_REGISTERED", "力矩工具未登记: " + toolCode);
217	        }
218	        LocalDate todayUtc = LocalDate.now(clock.withZone(ZoneOffset.UTC));
219	        if (!tool.calibrationDate().isEqual(todayUtc)) {
220	            // 日校验逾期（或提前日期）使用直接拒绝。
221	            throw ApiException.unprocessable("TOOL_CALIBRATION_EXPIRED",
222	                    "力矩工具 " + toolCode + " 日校验日期 " + tool.calibrationDate()
223	                            + " 非当日(UTC " + todayUtc + ")，禁止使用");
224	        }
225	    }
226	
227	    // ------------------------------------------------------------------
228	    // 自检互检
229	    // ------------------------------------------------------------------
230	
231	    @Override
232	    public Outcome inspect(InspectionRequest request) {
233	        return idempotencyExecutor.execute(request.requestId(), "INSPECTION", request, () -> {
234	            CardRow card = requireCard(request.cardNo());
235	            if (card.status() != CardStatus.TIGHTENED) {
236	                throw ApiException.unprocessable("CARD_NOT_TIGHTENED",
237	                        "力矩紧固未完成（当前 " + card.status() + "），不能自检互检");
238	            }
239	            if (request.selfInspector().equals(request.mutualInspector())) {
240	                throw ApiException.unprocessable("SELF_MUTUAL_SAME_PERSON",
241	                        "自检与互检须不同人员，同一人双签拒绝");
242	            }
243	            Instant now = clock.instant();
244	            try {
245	                inspectionRepository.insert(card.id(), request.selfInspector(),
246	                        request.mutualInspector(), request.requestId(), now);
247	            } catch (DuplicateKeyException duplicate) {
248	                throw ApiException.conflict("INSPECTION_EXISTS", "该工序卡已完成自检互检");
249	            }
250	            cardRepository.updateStatus(card.id(), CardStatus.INSPECTED);
251	            card = requireCard(card.cardNo());
252	            return Outcome.of(200, new ActionResult("自检互检完成", card.cardNo(), card.status().name()));
253	        });
254	    }
255	
256	    // ------------------------------------------------------------------
257	    // H 点见证
258	    // ------------------------------------------------------------------
259	
260	    @Override
261	    public Outcome witness(WitnessRequest request) {
262	        return idempotencyExecutor.execute(request.requestId(), "WITNESS", request, () -> {
263	            CardRow card = requireCard(request.cardNo());
264	            if (!"H".equals(card.witnessPoint())) {
265	                throw ApiException.unprocessable("NOT_H_POINT", "非 H 点工序，无需见证");
266	            }
267	            if (card.status() != CardStatus.INSPECTED
268	                    && card.status() != CardStatus.WAITING_WITNESS
269	                    && card.status() != CardStatus.ESCALATED) {
270	                throw ApiException.unprocessable("INSPECTION_REQUIRED",
271	                        "自检互检未完成（当前 " + card.status() + "），不能发起见证");
272	            }
273	            Instant now = clock.instant();
274	            int seq = witnessRepository.countByCard(card.id()) + 1;
275	
276	            if ("PRESENT".equals(request.action())) {
277	                if (request.witnessName() == null || request.witnessName().isBlank()) {
278	                    throw ApiException.badRequest("WITNESS_NAME_REQUIRED", "见证到场须提供见证人");
279	                }
280	                WitnessRepository.WitnessRow latest = witnessRepository.findLatest(card.id());
281	                if (latest != null && latest.status() == WitnessStatus.PRESENT) {
282	                    throw ApiException.conflict("WITNESS_ALREADY_PRESENT", "H 点已见证到场");
283	                }
284	                witnessRepository.append(card.id(), seq, WitnessStatus.PRESENT, request.witnessName(),
285	                        now, request.requestId(), "见证人到场签署");
286	                cardRepository.updateStatus(card.id(), CardStatus.WITNESSED);
287	                card = requireCard(card.cardNo());
288	                return Outcome.of(200, new WitnessResult(card.cardNo(), seq, WitnessStatus.PRESENT.name(),
289	                        request.witnessName(), card.status().name(), now, null, null, false, "见证人到场签署"));
290	            }
291	
292	            // ABSENT：缺席 → 等待。起始时间取首次缺席时间（重复缺席不重置 2 小时计时）。
293	            WitnessRepository.WitnessRow latest = witnessRepository.findLatest(card.id());
294	            if (latest != null && (latest.status() == WitnessStatus.PRESENT)) {
295	                throw ApiException.conflict("WITNESS_ALREADY_PRESENT", "H 点已见证，不能再报缺席");
296	            }
297	            Instant waitingSince = findWaitingSince(card.id(), now);
298	            witnessRepository.append(card.id(), seq, WitnessStatus.ABSENT, null, now,
299	                    request.requestId(), "见证缺席");
300	            witnessRepository.append(card.id(), seq + 1, WitnessStatus.WAITING, null, now,
301	                    request.requestId(), "见证缺席，转等待");
302	            cardRepository.updateStatusIfCurrent(card.id(), CardStatus.INSPECTED, CardStatus.WAITING_WITNESS);
303	            card = requireCard(card.cardNo());
304	            Instant escalateAt = waitingSince.plus(WITNESS_WAIT_LIMIT);
305	            return Outcome.of(200, new WitnessResult(card.cardNo(), seq + 1, WitnessStatus.WAITING.name(),
306	                    null, card.status().name(), now, waitingSince, escalateAt, false,
307	                    "见证缺席，转等待；满 2 小时(UTC)升级"));
308	        });
309	    }
310	
311	    private Instant findWaitingSince(long cardId, Instant fallback) {
312	        for (WitnessRepository.WitnessRow row : witnessRepository.listByCard(cardId)) {
313	            if (row.status() == WitnessStatus.ABSENT || row.status() == WitnessStatus.WAITING) {
314	                return row.eventTime();
315	            }
316	        }
317	        return fallback;
318	    }
319	
320	    @org.springframework.transaction.annotation.Transactional
321	    @Override
322	    public Outcome checkEscalation(String cardNo) {
323	        CardRow card = requireCard(cardNo);
324	        Instant now = clock.instant();
325	        WitnessRepository.WitnessRow latest = witnessRepository.findLatest(card.id());
326	        if (latest == null) {
327	            throw ApiException.unprocessable("NO_WITNESS_EVENT", "尚无见证事件");
328	        }
329	        Instant waitingSince = findWaitingSince(card.id(), latest.eventTime());
330	        Instant escalateAt = waitingSince.plus(WITNESS_WAIT_LIMIT);
331	        boolean due = !now.isBefore(escalateAt); // 恰满 2 小时判定为升级
332	
333	        if (card.status() == CardStatus.ESCALATED || latest.status() == WitnessStatus.ESCALATED) {
334	            return Outcome.of(200, new WitnessResult(card.cardNo(), latest.seq(),
335	                    WitnessStatus.ESCALATED.name(), null, card.status().name(), latest.eventTime(),
336	                    waitingSince, escalateAt, true, "等待满 2 小时，已升级"));
337	        }
338	        if (card.status() == CardStatus.WITNESSED || latest.status() == WitnessStatus.PRESENT) {
339	            return Outcome.of(200, new WitnessResult(card.cardNo(), latest.seq(),
340	                    latest.status().name(), latest.witnessName(), card.status().name(), latest.eventTime(),
341	                    null, null, false, "见证已到场，无需升级"));
342	        }
343	        if (!due) {
344	            return Outcome.of(200, new WitnessResult(card.cardNo(), latest.seq(),
345	                    latest.status().name(), null, card.status().name(), now,
346	                    waitingSince, escalateAt, false, "等待未满 2 小时，暂不升级"));
347	        }
348	        int seq = witnessRepository.countByCard(card.id()) + 1;
349	        // 以状态条件更新作为升级受理判据：并发调用只有一方成功并追加升级链事件。
350	        boolean won = cardRepository.updateStatusIfCurrent(
351	                card.id(), CardStatus.WAITING_WITNESS, CardStatus.ESCALATED);
352	        if (!won) {
353	            card = requireCard(card.cardNo());
354	            WitnessRepository.WitnessRow winner = witnessRepository.findLatest(card.id());
355	            return Outcome.of(200, new WitnessResult(card.cardNo(), winner.seq(),
356	                    WitnessStatus.ESCALATED.name(), null, card.status().name(), winner.eventTime(),
357	                    waitingSince, escalateAt, true, "等待满 2 小时，已升级"));
358	        }
359	        witnessRepository.append(card.id(), seq, WitnessStatus.ESCALATED, null, now,
360	                "SYSTEM_ESCALATION", "等待满 2 小时（含恰满边界），升级处理");
361	        card = requireCard(card.cardNo());
362	        return Outcome.of(200, new WitnessResult(card.cardNo(), seq, WitnessStatus.ESCALATED.name(),
363	                null, card.status().name(), now, waitingSince, escalateAt, true,
364	                "等待满 2 小时（含恰满边界），升级处理"));
365	    }
366	
367	    // ------------------------------------------------------------------
368	    // 覆盖工序与放行归档
369	    // ------------------------------------------------------------------
370	
371	    @Override
372	    public Outcome coverage(CoverageRequest request) {
373	        return idempotencyExecutor.execute(request.requestId(), "COVERAGE", request, () -> {
374	            CardRow card = requireCard(request.cardNo());
375	            if ("H".equals(card.witnessPoint())) {
376	                if (card.status() != CardStatus.WITNESSED) {
377	                    // H 点未见证（缺席/等待/升级）不得进入覆盖工序。
378	                    throw ApiException.unprocessable("WITNESS_REQUIRED",
379	                            "H 点工序未见证到场（当前 " + card.status() + "），不得进入覆盖工序");
380	                }
381	            } else if (card.status() != CardStatus.INSPECTED
382	                    && card.status() != CardStatus.WITNESSED
383	                    && card.status() != CardStatus.ARCHIVED) {
384	                throw ApiException.unprocessable("INSPECTION_REQUIRED",
385	                        "自检互检未完成（当前 " + card.status() + "），不得进入覆盖工序");
386	            }
387	            return Outcome.of(200, new ActionResult(
388	                    "允许进入覆盖工序: " + request.nextOperation(), card.cardNo(), card.status().name()));
389	        });
390	    }
391	
392	    @Override
393	    public Outcome release(ReleaseRequest request) {
394	        return idempotencyExecutor.execute(request.requestId(), "RELEASE", request, () -> {
395	            CardRow card = requireCard(request.cardNo());
396	            // 终态重复归档：幂等成功（即使是新 requestId）。
397	            if (card.status() == CardStatus.ARCHIVED) {
398	                ReleaseRepository.ReleaseRow existing = releaseRepository.findByCard(card.id());
399	                return Outcome.of(200, new ActionResult(
400	                        "工序卡已归档（幂等），首次归档 requestId=" + existing.requestId(),
401	                        card.cardNo(), CardStatus.ARCHIVED.name()));
402	            }
403	            if (card.status() == CardStatus.QUARANTINED) {
404	                throw ApiException.unprocessable("CARD_QUARANTINED", "整批隔离评审中，不得放行归档");
405	            }
406	            if ("H".equals(card.witnessPoint())) {
407	                if (card.status() != CardStatus.WITNESSED) {
408	                    throw ApiException.unprocessable("WITNESS_REQUIRED",
409	                            "H 点未见证到场（当前 " + card.status() + "），不得放行");
410	                }
411	            } else if (card.status() != CardStatus.INSPECTED) {
412	                throw ApiException.unprocessable("INSPECTION_REQUIRED",
413	                        "自检互检未完成（当前 " + card.status() + "），不得放行");
414	            }
415	            Instant now = clock.instant();
416	            releaseRepository.insert(card.id(), request.releasedBy(), request.requestId(), now);
417	            cardRepository.markArchived(card.id(), now);
418	            cardRepository.releaseGuard(card.station());
419	            return Outcome.of(200, new ActionResult("放行归档完成（终态）",
420	                    request.cardNo(), CardStatus.ARCHIVED.name()));
421	        });
422	    }
423	
424	    // ------------------------------------------------------------------
425	    // 查询与复算
426	    // ------------------------------------------------------------------
427	
428	    @Override
429	    public CardView getCard(String cardNo) {
430	        return toView(requireCard(cardNo));
431	    }
432	
433	    @Override
434	    public TraceView trace(String cardNo) {
435	        CardRow card = requireCard(cardNo);
436	        List<FastenerRow> fasteners = cardRepository.listFasteners(card.id());
437	        java.util.Map<Long, String> pointNames = new java.util.HashMap<>();
438	        for (FastenerRow f : fasteners) {
439	            pointNames.put(f.id(), f.pointCode());
440	        }
441	
442	        List<TraceView.TorquePoint> curve = new ArrayList<>();
443	        for (TorqueRepository.TorqueRow t : torqueRepository.listTorqueByCard(card.id())) {
444	            FastenerRow f = fasteners.stream()
445	                    .filter(x -> x.id() == t.fastenerId()).findFirst().orElse(null);
446	            curve.add(new TraceView.TorquePoint(
447	                    pointNames.getOrDefault(t.fastenerId(), "?"),
448	                    t.attemptNo(),
449	                    f == null ? null : f.nominalTorque(),
450	                    t.measuredTorque(), t.deviationPct(), t.inTolerance(),
451	                    t.operator(), t.toolCode(), t.measuredAt()));
452	        }
453	
454	        List<TraceView.WitnessPoint> witnessChain = new ArrayList<>();
455	        for (WitnessRepository.WitnessRow w : witnessRepository.listByCard(card.id())) {
456	            witnessChain.add(new TraceView.WitnessPoint(
457	                    w.seq(), w.status().name(), w.witnessName(), w.eventTime(), w.note()));
458	        }
459	
460	        List<TraceView.ReworkPoint> reworkLedger = new ArrayList<>();
461	        for (TorqueRepository.ReworkRow r : torqueRepository.listReworksByCard(card.id())) {
462	            reworkLedger.add(new TraceView.ReworkPoint(
463	                    pointNames.getOrDefault(r.fastenerId(), "?"),
464	                    r.reworkNo(), r.requestId(), r.reason(), r.createdAt()));
465	        }
466	        return new TraceView(card.cardNo(), card.status().name(), curve, witnessChain, reworkLedger);
467	    }
468	
469	    @Override
470	    public ActionResult registerTool(ToolRegisterRequest request) {
471	        toolRepository.upsert(request.toolCode(), request.calibrationDate());
472	        return new ActionResult("力矩工具已登记日校验日期 " + request.calibrationDate()
473	                + "（UTC，仅当日有效）", request.toolCode(), "TOOL_REGISTERED");
474	    }
475	
476	    // ------------------------------------------------------------------
477	    // 辅助
478	    // ------------------------------------------------------------------
479	
480	    private CardRow requireCard(String cardNo) {
481	        CardRow card = cardRepository.findByCardNo(cardNo);
482	        if (card == null) {
483	            throw ApiException.notFound("CARD_NOT_FOUND", "工序卡不存在: " + cardNo);
484	        }
485	        return card;
486	    }
487	
488	    private CardView toView(CardRow card) {
489	        return new CardView(card.cardNo(), card.station(), card.productSn(), card.witnessPoint(),
490	                card.status().name(), card.operator(), card.dispatchedAt(),
491	                card.quarantinedAt(), card.archivedAt());
492	    }
493	}
