75	        jdbcTemplate.update(
76	                "INSERT INTO torque_record (card_id, fastener_id, attempt_no, measured_torque, deviation_pct, "
77	                        + "in_tolerance, operator, tool_code, measured_at, request_id, created_at) "
78	                        + "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
79	                row.cardId(), row.fastenerId(), row.attemptNo(), row.measuredTorque(), row.deviationPct(),
