package com.example.starter.domain;

/**
 * 工具采集会话状态机。
 *
 * <p>{@link #OPEN} 采集中，可上传批次；{@link #CLOSED} 已关闭（终态），
 * 关闭要求无缺号且全部缓冲包已消费；工序归档前全部采集会话须关闭。
 */
public enum AcquisitionSessionStatus {
    /** 采集中，受理批次上传。 */
    OPEN,
    /** 已关闭（终态），不再受理普通批次；归档后迟到包仍只记迟到。 */
    CLOSED
}

package com.example.starter.domain;

/**
 * 采集原始包状态。
 *
 * <p>{@link #BUFFERED} 乱序缓冲中（水位线之后第 1～20 号窗口内，尚未形成连续前缀，
 * 不参与自检互检与见证放行）；{@link #CONSUMED} 已按序入财力矩链；
 * {@link #LATE} 工序归档后到达，只记迟到事件，不复活卡片。
 */
public enum AcquisitionPacketStatus {
    /** 乱序缓冲中，等待缺号补齐后按序入账。 */
    BUFFERED,
    /** 已随连续完整前缀入财力矩链。 */
    CONSUMED,
    /** 归档后迟到，仅登记迟到事件。 */
    LATE
}

